#!/usr/bin/env node
// Patch the generated iOS Info.plist with keys Capacitor doesn't manage:
//   · ITSAppUsesNonExemptEncryption=false — HTTPS-only ⇒ export-compliance exempt, so
//     TestFlight uploads don't stall on the encryption question.
//   · NSMicrophoneUsageDescription — the audio apps record/detect what you sing or play;
//     without a usage string iOS crashes the first mic access (and App Review rejects).
// The native ios/ project is regenerated by `cap add`/`cap sync`, so these must be RE-APPLIED
// each time — `npm run app:add-ios` and the CI workflow both call this after sync. Idempotent.
import { execFileSync } from 'node:child_process'
import { existsSync } from 'node:fs'

const PLIST = 'ios/App/App/Info.plist'
if (!existsSync(PLIST)) {
  console.error(`no ${PLIST} — run \`npx cap add ios\` first`)
  process.exit(1)
}

// [key, PlistBuddy type, value]
const KEYS = [
  ['ITSAppUsesNonExemptEncryption', 'bool', 'false'],
  ['NSMicrophoneUsageDescription', 'string', '100Lights uses the microphone to record and detect the notes you sing or play.'],
]

const pb = (cmd) => execFileSync('/usr/libexec/PlistBuddy', ['-c', cmd, PLIST], { stdio: ['ignore', 'pipe', 'ignore'] })
for (const [key, type, value] of KEYS) {
  try { pb(`Add :${key} ${type} ${value}`) }
  catch { pb(`Set :${key} ${value}`) } // already present → overwrite
  console.log(`✓ ${key} = ${value}`)
}
